# ---------------------------------------------------------------------------------
# Automatically creates captials_table.s
# from JSON file https://raw.githubusercontent.com/Ginden/capitals/refs/heads/master/europe.json
# ---------------------------------------------------------------------------------
import json
from unidecode import unidecode

with open('europe.json', 'r') as f:
    europe = json.loads(f.read())

HEADER = f""";----------------------------------------------------
; Table containing: Country, Capitals for each country in europe
; Autogenerated using python
;----------------------------------------------------------------

CAPITALS_TABLE_SIZE    EQU {len(europe)}

"""

output = ""
for index, country_data in enumerate(europe):
    country = unidecode(country_data["properties"]["country"])
    capital = unidecode(country_data["properties"]["capital"])

    output += f'capitals_country{index} defb "\\f{country}\\n\\0"\n'
    output += f'capitals_capital{index} defb "{capital}\\0"\n'

output += "align\n\n"

output += "capitals_table defw capitals_country0, capitals_capital0\n"

for index in range(1, len(europe)):
    output += f"               defw capitals_country{index}, capitals_capital{index}\n"


with open('capitals_table.s', 'w') as f:
    f.write(HEADER + output)
